package jsonpath

// node is one element of a parsed JSONPath template. The parser builds a tree
// of these; the evaluator walks it with a type switch.
type node interface {
	node()
}

// listNode is an ordered sequence of nodes. The root of every parsed template
// is a listNode whose children are either textNodes (literal text outside
// "{}") or further listNodes (one per "{...}" action).
type listNode struct{ nodes []node }

// textNode is literal text: either text outside an action, or a quoted string
// inside one.
type textNode struct{ text string }

// fieldNode selects a named field from a map or struct.
type fieldNode struct{ value string }

// identifierNode is a bare word inside an action. Only "range" and "end" are
// meaningful; anything else fails at evaluation time.
type identifierNode struct{ name string }

// wildcardNode selects every child of the current value.
type wildcardNode struct{}

// recursiveNode ("..") selects the current value and, recursively, every
// container nested inside it.
type recursiveNode struct{}

// intNode is an integer literal.
type intNode struct{ value int }

// floatNode is a floating-point literal.
type floatNode struct{ value float64 }

// boolNode is a "true"/"false" literal.
type boolNode struct{ value bool }

// sliceParam is one of the three components of an array subscript. known
// records whether the component was written explicitly; derived marks an end
// bound that the parser synthesised for a plain "[n]" index, which the
// evaluator needs in order to resolve negative indices.
type sliceParam struct {
	value   int
	known   bool
	derived bool
}

// arrayNode is an array subscript: an index, or a [start:end:step] slice.
type arrayNode struct{ params [3]sliceParam }

// filterNode is a "[?(left op right)]" expression. operator is "exists" when
// the expression has no comparison, in which case right is empty.
type filterNode struct {
	left     *listNode
	right    *listNode
	operator string
}

// unionNode is a comma-separated subscript such as "[0,2]" or "['a','b']".
// Each branch is evaluated against the same input and the results concatenated.
type unionNode struct{ nodes []*listNode }

func (*listNode) node()       {}
func (*textNode) node()       {}
func (*fieldNode) node()      {}
func (*identifierNode) node() {}
func (*wildcardNode) node()   {}
func (*recursiveNode) node()  {}
func (*intNode) node()        {}
func (*floatNode) node()      {}
func (*boolNode) node()       {}
func (*arrayNode) node()      {}
func (*filterNode) node()     {}
func (*unionNode) node()      {}

func (l *listNode) append(n node) { l.nodes = append(l.nodes, n) }
